signal term_highlighted(term_name: String)

var highlighted_term := ""

func highlight_term(term_name: String) -> void:
	highlighted_term = term_name
	for key in term_nodes.keys():
		var mat: StandardMaterial3D = materials[key]
		if key == term_name:
			mat.emission_energy_multiplier = 2.0
		else:
			mat.emission_energy_multiplier = 0.3
	term_highlighted.emit(term_name)

func _process(delta: float) -> void:
	if animate and highlighted_term != "":
		var pulse = 1.0 + sin(Time.get_ticks_msec() * 0.001 * pulse_speed) * 0.3
		materials[highlighted_term].emission_energy_multiplier = 2.0 * pulse
